            pattern = tuple(tuple(grid[y][x] for x in range(c0, c1 + 1, scale))
                            for y in range(r0, r1 + 1, scale))
            mask = tuple(tuple(v != bg for v in row) for row in pattern)
            colors = set(v for row in pattern for v in row
                         if v not in (bg, 1, 2))
            objects.append({'r0': r0, 'c0': c0, 'scale': scale,
                            'pattern': pattern, 'mask': mask,
                            'colors': colors})

    mask_counts = Counter(obj['mask'] for obj in objects)
    common_mask, count = mask_counts.most_common(1)[0]
    if count > 1:
        common = [obj for obj in objects if obj['mask'] == common_mask]
        odd = next(obj for obj in objects if obj['mask'] != common_mask)
    else:
        frequency = Counter()
        for obj in objects:
            frequency.update(obj['colors'])
        majority = frequency.most_common(1)[0][0]
        common = [obj for obj in objects if majority in obj['colors']]
        odd = next(obj for obj in objects if majority not in obj['colors'])
    template = common[0]

    result = [row[:] for row in grid]

    def orient(pattern, source, target):
        if source['mask'] != target['mask']:
            if tuple(reversed(source['mask'])) == target['mask']:
                return tuple(reversed(pattern))
        return pattern

